def count_up_to(n):
    """Implement a function that takes an non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    if n <= 2:
        return []

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)
    return primes

def sort_array(arr):
    """
    In this Kata, you have to sort an array of non-negative integers according to
    number of ones in their binary representation in ascending order.
    For similar number of ones, sort based on decimal value.

    It must be implemented like this:
    >>> sort_array([1, 5, 2, 3, 4]) == [1, 2, 3, 4, 5]
    >>> sort_array([-2, -3, -4, -5, -6]) == [-6, -5, -4, -3, -2]
    >>> sort_array([1, 0, 2, 3, 4]) == [0, 1, 2, 3, 4]
    """
    def count_ones(n):
        # For negative numbers, we need to handle them properly
        # In Python, negative numbers have infinite leading 1s in two's complement
        # But the problem says "non-negative integers", so negative numbers might be edge cases
        # Let's use bin() which gives the binary representation with a minus sign for negatives
        # For negative numbers, bin(-2) = '-0b10', so we need to count ones in the absolute value part
        if n >= 0:
            return bin(n).count('1')
        else:
            # For negative numbers, count ones in the binary representation of the absolute value
            # This is a reasonable interpretation since the problem mentions non-negative integers
            return bin(abs(n)).count('1')

    return sorted(arr, key=lambda x: (count_ones(x), x))

def valid_date(date):
    """You have to write a function which validates a given date string and
    returns True if the date is valid otherwise False.
    The date is valid if all of the following rules are satisfied:
    1. The date string is not empty.
    2. The number of days is not less than 1 or higher than 31 days for months 1,3,5,7,8,10,12. And the number of days is not less than 1 or higher than 30 days for months 4,6,9,11. And, the number of days is not less than 1 or higher than 29 for the month 2.
    3. The months should not be less than 1 or higher than 12.
    4. The date should be in the format: mm-dd-yyyy

    for example: 
    valid_date('03-11-2000') => True

    valid_date('15-01-2012') => False

    valid_date('04-0-2040') => False

    valid_date('06-04-2020') => True

    valid_date('06/04/2020') => False
    """
    # Rule 1: The date string is not empty.
    if not date:
        return False

    # Rule 4: The date should be in the format: mm-dd-yyyy
    # Check that it has exactly 3 parts separated by '-'
    parts = date.split('-')
    if len(parts) != 3:
        return False

    # Check that each part is a valid integer string (only digits, no empty strings)
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False

    # Parse the parts
    try:
        month = int(parts[0])
        day = int(parts[1])
        year = int(parts[2])
    except ValueError:
        return False

    # Rule 3: The months should not be less than 1 or higher than 12.
    if month < 1 or month > 12:
        return False

    # Rule 2: Check days based on month
    # Months with 31 days: 1, 3, 5, 7, 8, 10, 12
    # Months with 30 days: 4, 6, 9, 11
    # Month 2: up to 29 days
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False

    return True
